    };

    const updateWaves = (frameCtx: GameCtx): void => {
      waveDirector.update(
        frameCtx,
        waveTargets.filter(({ target }) => target.alive).length,
        spawnWave,
        (wave) => {
          const state = frameCtx.state.getState();
