      hitscan.update(dt);
      updateProjectiles(frameCtx, dt);
      for (const target of targets.values()) target.update(dt);
      pickup.update(dt);
      removeDeadTargets();
      updateWaves(frameCtx);
      syncStateAndHud(frameCtx);
      rig.follow(player.mesh.position, dt);
    };
  }
}

