import type { ICtx, ScheduleHandle } from "@threenative/core";
import { attachToBone } from "@threenative/core";
import { CharacterBody3D, CollisionShape3D, type IPhysicsContext } from "@threenative/physics";
import { Bone, Group, Skeleton, SkeletonHelper, Vector3 } from "three";
import { directSpaceState } from "../physics.js";
import { createPatrolEnemyVisual, createRifleVisual } from "../render/shapes.js";
import type { GameState } from "../state.js";
import { HOSTILE_LAYER, PLAYER_LAYER, WORLD_LAYER } from "./Player.js";

type GameCtx = ICtx<GameState, IPhysicsContext>;

const PATROL_SPEED = 2.5;
const CHASE_SPEED = 3.8;
const CHASE_RANGE = 12;
const FIRE_RATE = 4;
const VIEW_RANGE = 10;

export class PatrolEnemy {
  readonly mesh: Group;
  readonly body: CharacterBody3D;
  readonly tags = ["hostile", "patrol-enemy"];
  health: number;
  alive = true;
  chasing = false;
  #patrolPoints: Vector3[];
  #currentPatrolIndex = 0;
  #velocity = new Vector3();
  #fireTimer = 0;
  #onFire: (origin: Vector3) => void;
  #scanHandle: ScheduleHandle | undefined;
  #skeleton: Skeleton;
  #rightHandBone: Bone;

  constructor(
    ctx: GameCtx,
    materials: Parameters<typeof createPatrolEnemyVisual>[0],
    position: Vector3,
    patrolPoints: Vector3[] = [],
    options: {
      readonly health?: number;
      readonly onFire?: (origin: Vector3) => void;
    } = {},
  ) {
    this.health = options.health ?? 50;
    this.#onFire = options.onFire ?? (() => undefined);
    this.#patrolPoints = patrolPoints.length > 0 ? patrolPoints : [position.clone()];

    // Create visual with skeleton for bone attachment
    this.mesh = createPatrolEnemyVisual(materials);
    this.mesh.position.copy(position);

    // Create skeleton for rifle attachment
    const bones: Bone[] = [];
    const rootBone = new Bone();
    rootBone.name = "Root";
    bones.push(rootBone);

    const pelvisBone = new Bone();
    pelvisBone.name = "Pelvis";
    pelvisBone.position.y = 0.7;
    rootBone.add(pelvisBone);
    bones.push(pelvisBone);

    const spineBone = new Bone();
    spineBone.name = "Spine";
    spineBone.position.y = 0.35;
    pelvisBone.add(spineBone);
    bones.push(spineBone);

    const shoulderBone = new Bone();
    shoulderBone.name = "Shoulder";
    shoulderBone.position.y = 0.5;
    spineBone.add(shoulderBone);
    bones.push(shoulderBone);

    // Right arm
    const rightShoulderBone = new Bone();
    rightShoulderBone.name = "RightShoulder";
    rightShoulderBone.position.x = -0.25;
    shoulderBone.add(rightShoulderBone);
    bones.push(rightShoulderBone);

    const rightArmBone = new Bone();
    rightArmBone.name = "RightArm";
    rightArmBone.position.y = -0.3;
    rightShoulderBone.add(rightArmBone);
    bones.push(rightArmBone);

    this.#rightHandBone = new Bone();
    this.#rightHandBone.name = "RightHand";
    this.#rightHandBone.position.y = -0.3;
    rightArmBone.add(this.#rightHandBone);
    bones.push(this.#rightHandBone);

    this.#skeleton = new Skeleton(bones);
    this.mesh.add(rootBone);

    // Create and attach rifle
    const rifle = createRifleVisual(materials);
    rifle.position.set(0, 0, 0);
    attachToBone(this.mesh, "RightHand", rifle);

    ctx.add(this.mesh);
    this.body = new CharacterBody3D({
      collisionLayer: HOSTILE_LAYER,
      collisionMask: WORLD_LAYER | PLAYER_LAYER,
      autostep: { maxHeight: 0.25, minWidth: 0.18 },
      object: this.mesh,
      physics: ctx.physics,
      shape: CollisionShape3D.capsule(0.35, 0.38),
    });
  }

  startVision(ctx: GameCtx, playerBodyId: number): void {
    const scan = (): void => {
      if (!this.alive) return;
      const playerPos = ctx.entities.get("player")?.mesh?.position;
      if (!playerPos) {
        this.#scanHandle = ctx.after(0.1, scan);
        return;
      }
      const distToPlayer = this.mesh.position.distanceTo(playerPos);

      // Check if player is in range
      if (distToPlayer < VIEW_RANGE) {
        const direction = playerPos.clone().sub(this.mesh.position).normalize();
        const rayOrigin = this.mesh.position.clone().add(new Vector3(0, 0.7, 0));
        const rayEnd = rayOrigin.clone().add(direction.multiplyScalar(VIEW_RANGE));

        const hits = directSpaceState(ctx.physics).intersectRay({
          collisionMask: PLAYER_LAYER,
          from: rayOrigin,
          to: rayEnd,
        });

        this.chasing = hits.some((hit) => hit.body.id === playerBodyId);
      } else {
        this.chasing = false;
      }

      this.#scanHandle = ctx.after(0.1, scan);
    };
    this.#scanHandle = ctx.after(0.1, scan);
  }

  update(ctx: GameCtx, dt: number): void {
    if (!this.alive) return;

    const playerPos = (ctx.entities.get("player") as any)?.mesh?.position;

    // Movement
    if (this.chasing && playerPos) {
      const direction = playerPos.clone().sub(this.mesh.position).normalize();
      this.#velocity.x = direction.x * CHASE_SPEED;
      this.#velocity.z = direction.z * CHASE_SPEED;
    } else {
      // Patrol behavior
      const targetPoint = this.#patrolPoints[this.#currentPatrolIndex];
      const direction = targetPoint.clone().sub(this.mesh.position);

      if (direction.length() < 0.5) {
        this.#currentPatrolIndex = (this.#currentPatrolIndex + 1) % this.#patrolPoints.length;
      } else {
        direction.normalize();
        this.#velocity.x = direction.x * PATROL_SPEED;
        this.#velocity.z = direction.z * PATROL_SPEED;
      }
    }

    this.body.velocity.x = this.#velocity.x;
    this.body.velocity.z = this.#velocity.z;
    this.body.moveAndSlide(dt);

    // Firing
    if (!this.chasing || !playerPos) {
      this.#fireTimer = FIRE_RATE;
      return;
    }

    this.#fireTimer -= dt;
    if (this.#fireTimer > 0) return;
    this.#fireTimer = FIRE_RATE;
    this.#onFire(this.mesh.position.clone().add(new Vector3(0, 0.9, 0)));
  }

  takeDamage(amount: number): boolean {
    if (!this.alive || !Number.isFinite(amount) || amount <= 0) return false;
    this.health = Math.max(0, this.health - amount);
    if (this.health > 0) return false;
    this.alive = false;
    this.mesh.visible = false;
    return true;
  }

  debug(): Record<string, unknown> {
    return {
      alive: this.alive,
      chasing: this.chasing,
      health: this.health,
      position: this.mesh.position.toArray(),
    };
  }

  dispose(): void {
    this.#scanHandle?.cancel();
    this.body.dispose();
    this.mesh.removeFromParent();
  }
}

