  if (this.chasing && playerPos) {
    const direction = playerPos.clone().sub(this.mesh.position).normalize();
    this.#velocity.x = direction.x * CHASE_SPEED;
    this.#velocity.z = direction.z * CHASE_SPEED;
  } else {
    // Patrol behavior
    const targetPoint = this.#patrolPoints[this.#currentPatrolIndex];
    const direction = targetPoint.clone().sub(this.mesh.position);

    if (direction.length() < 0.5) {
      this.#currentPatrolIndex = (this.#currentPatrolIndex + 1) % this.#patrolPoints.length;
    } else {
      direction.normalize();
      this.#velocity.x = direction.x * PATROL_SPEED;
      this.#velocity.z = direction.z * PATROL_SPEED;
    }
  }

  this.body.velocity.x = this.#velocity.x;
  this.body.velocity.z = this.#velocity.z;
  this.body.moveAndSlide(dt);

  // Firing
  if (!this.chasing || !playerPos) {
    this.#fireTimer = FIRE_RATE;
    return;
  }

  this.#fireTimer -= dt;
  if (this.#fireTimer > 0) return;
  this.#fireTimer = FIRE_RATE;
  this.#onFire(this.mesh.position.clone().add(new Vector3(0, 0.9, 0)));
}

